function refreshPool(){let previous=null;try{previous=JSON.parse(localStorage.getItem('wr_game_state')||'null')?.book}catch{}let previousName=Array.from($('book').options).find(o=>o.value===previous)?.textContent||'Cả 4 quyển';if(total>0)saveRanking(false,previousName);runId=String(Date.now());localStorage.setItem('wr_run_id',runId);stage=1;total=0;globalWave=0;let b=$('book').value;pool=words.filter(w=>b==='all'||String(w.book)===b);startStage()}
