bindAnswerEvents($('answer'));$('mode').value=mode;$('voice').value=voiceChoice;$('voice').addEventListener('change',()=>{voiceChoice=$('voice').value;localStorage.setItem('wr_voice',voiceChoice);populateVoices()});for(let [id,key] of [['enVoice','wr_en_voice'],['viVoice','wr_vi_voice']])$(id).addEventListener('change',()=>localStorage.setItem(key,$(id).value));if('speechSynthesis'in window){populateVoices();speechSynthesis.addEventListener?.('voiceschanged',populateVoices)}else populateVoices();updateViSoundButton();$('viSound').addEventListener('click',()=>{viSoundOn=!viSoundOn;localStorage.setItem('wr_vi_sound',viSoundOn?'on':'off');updateViSoundButton();if(!viSoundOn&&currentSpeechLang==='vi-VN'&&'speechSynthesis'in window){speechRun++;speechSynthesis.cancel();currentSpeechLang=null}});$('replay').addEventListener('click',()=>{if(lastWord)sayPair(lastWord)});$('mode').addEventListener('change',refreshMode);$('book').addEventListener('change',refreshPool);updateSpeedButton();updatePauseButton();
