$('closeDaily').addEventListener('click',()=>{$('dailyOverlay').hidden=true});$('extraTime').addEventListener('click',()=>{localStorage.setItem('wr_overtime_key',dayKey());$('dailyOverlay').hidden=true;updateDaily();resumeGame()});
document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseGame()});document.addEventListener('pointerdown',()=>{lastActionAt=Date.now()});document.addEventListener('keydown',()=>{lastActionAt=Date.now()});window.addEventListener('pagehide',()=>{saveDaily();pauseGame()});
$('nextWave').addEventListener('click',()=>{if(paused||transitioning||!pool.length)return;queue.unshift(...active.map(e=>e.word));startWave()});
$('continue').addEventListener('click',advanceStage);$('ranking').addEventListener('click',openRanking);$('closeRanking').addEventListener('click',closeRanking);$('rankingOverlay').addEventListener('click',e=>{if(e.target===$('rankingOverlay'))closeRanking()});
fetch('words.json').then(r=>r.json()).then(data=>{words=data.filter(w=>w.en&&w.vi);restoreOrStart();if(document.hidden)pauseGame()}).catch(()=>message('Không tải được dữ liệu từ vựng. Hãy tải lại trang.'));
